<script setup>
import { computed } from 'vue';
import { stateName, factoryName, prettyTime } from './api';
const props = defineProps({ run: Object });
const emit = defineEmits(['retry', 'cancel', 'confirm', 'export', 'source']);
const report = computed(() => props.run?.report);
const children = computed(() => { const map = new Map(); for (const c of props.run?.children || []) map.set(c.factory, c); return map; });
</script>
<template>
  <section class="panel report-board">
    <div class="section-heading"><div><span class="eyebrow">MULTI-AGENT WORKSPACE</span><h3>{{ run.period }} · 工厂协作月报</h3><p class="muted small">{{ run.template }} 模板 · 本次 {{ run.factory_ids?.length }}/12 厂 · {{ prettyTime(run.created_at) }}</p></div><span class="tag" :class="run.state === 'success' ? 'green' : ['partial','needs_input'].includes(run.state) ? 'amber' : ''">{{ stateName(run.state) }}</span></div>
    <div class="orchestrator"><span class="agent-avatar">✦</span><div><strong>Main Agent · 总部协调</strong><small>分派工厂任务 → 校验来源 → 汇总交付</small></div><span class="tag">第 {{ run.attempt }} 次办理</span></div>
    <div class="factory-agent-grid"><article v-for="factory in run.factory_ids" :key="factory" class="factory-agent-card"><header><span class="factory-avatar">{{ factory.slice(1) }}</span><div><strong>{{ factoryName(factory) }} Agent</strong><small>独立工厂任务</small></div></header><span class="status-line"><i :class="children.get(factory)?.state" />{{ stateName(children.get(factory)?.state || (['failed','cancelled'].includes(run.state) ? '未启动' : 'queued')) }}</span><p v-if="children.get(factory)?.report?.metrics" class="factory-count"><strong>{{ children.get(factory).report.metrics.total }}</strong> 台设备已核验</p><p v-else class="muted small">{{ children.get(factory)?.report?.missing?.[0] || children.get(factory)?.error?.message || '等待 Main Agent 分派' }}</p><details v-if="children.get(factory)?.trace?.length" class="trace-details"><summary>执行轨迹</summary><div v-for="(t,i) in children.get(factory).trace" :key="i" class="trace-item"><span>{{ t.action }}</span><span>{{ stateName(t.state) }}</span></div></details></article></div>
    <div v-if="run.error" class="inline-error">{{ run.error.message }}</div>
    <template v-if="report"><div class="report-banner" :class="{ 'partial-banner': report.missing_factories?.length }"><strong>{{ report.missing_factories?.length ? '部分结果已就绪' : '各厂结果已汇总' }}</strong><span>{{ report.missing_factories?.length ? `待补充：${report.missing_factories.map(factoryName).join('、')}。总数仅包含已覆盖工厂。` : `已覆盖 ${report.coverage} 厂，每项结果均可查看来源。` }}</span></div><div class="metric-grid report-metrics"><div><span>全部设备</span><strong>{{ report.metrics.total }}<small> 台</small></strong></div><div><span>工艺设备</span><strong>{{ report.metrics.process }}<small> 台</small></strong></div><div><span>计划完成率</span><strong>{{ report.metrics.completion_rate ?? '—' }}<small v-if="report.metrics.completion_rate != null"> %</small></strong></div><div><span>{{ run.template === 'V2' ? '停机设备' : '逾期未完成' }}</span><strong>{{ run.template === 'V2' ? report.metrics.stopped : report.metrics.overdue }}<small> {{ run.template === 'V2' ? '台' : '项' }}</small></strong></div></div><div class="table-wrap"><table><thead><tr><th>工厂 / 来源</th><th>全部</th><th>工艺</th><th>非工艺</th><th>待分类</th><th v-if="run.template === 'V2'">停机</th><th>状态</th></tr></thead><tbody><tr v-for="f in report.factories" :key="f.factory"><td><button class="text-button" :disabled="!f.metrics" @click="emit('source',f.source_ref)">{{ factoryName(f.factory) }} ↗</button></td><td>{{ f.metrics?.total ?? '—' }}</td><td>{{ f.metrics?.process ?? '—' }}</td><td>{{ f.metrics?.nonprocess ?? '—' }}</td><td>{{ f.metrics?.unclassified ?? '—' }}</td><td v-if="run.template === 'V2'">{{ f.metrics?.stopped ?? '—' }}</td><td>{{ stateName(f.status) }}</td></tr></tbody></table></div><p class="muted small">合成演示数据 · 截止 {{ report.cutoff }} · {{ run.report_state === 'confirmed' ? '已确认报告' : '报告草稿' }} · 各厂来源版本已锁定</p></template>
    <details v-if="report" class="business-detail"><summary>查看资产动向与检维修明细</summary><div class="table-wrap"><table><thead><tr><th>工厂</th><th>期内应完成</th><th>已完成</th><th>逾期未完成</th><th>按期完成</th></tr></thead><tbody><tr v-for="f in report.factories.filter(f => f.status === 'success')" :key="f.factory"><td>{{ factoryName(f.factory) }}</td><td>{{ f.plans?.due ?? '—' }}</td><td>{{ f.plans?.completed ?? '—' }}</td><td>{{ f.plans?.overdue ?? '—' }}</td><td>{{ f.plans?.on_time ?? '—' }}</td></tr></tbody></table></div><div v-for="f in report.factories.filter(f => f.status === 'success')" :key="f.factory" class="movement-section"><h4>{{ factoryName(f.factory) }} · 资产变化</h4><div v-for="e in f.confirmed_events" :key="e.id" class="compact-record"><div><strong>已确认状态变更</strong><small>{{ e.target }} · {{ e.after?.effective_date }} · {{ e.before?.equipment_state }} → {{ e.after?.equipment_state }}</small></div><button class="text-button" @click="emit('source',e.id)">查看事件 ↗</button></div><p v-if="!f.confirmed_events?.length" class="muted small">本期暂无已确认动向事件。</p><p class="muted small">两期盘点发现 {{ f.differences?.length || 0 }} 项差异；差异独立标记待核对，不自动当作调拨或报废。</p><div v-for="(d,i) in f.differences" :key="i" class="difference-row"><span>{{ d.kind }}</span><button class="text-button" @click="emit('source',d.asset_id)">{{ d.asset_id }} ↗</button><small>{{ d.before || '—' }} → {{ d.after || '—' }}</small></div></div></details>
    <div class="button-row"><button v-if="['partial','failed','timeout','interrupted'].includes(run.state) && run.report_state !== 'confirmed'" class="primary" @click="emit('retry')">补齐后重试未完成工厂</button><button v-if="['running','queued'].includes(run.state)" class="secondary" @click="emit('cancel')">取消任务</button><button v-if="run.state === 'success' && run.report_state !== 'confirmed'" class="primary" @click="emit('confirm')">确认报告版本</button><button v-if="report" class="secondary" @click="emit('export')">导出当前报告 CSV ↗</button></div>
    <details v-if="run.trace?.length" class="trace-details"><summary>Main Agent 执行记录</summary><div v-for="(t,i) in run.trace" :key="i" class="trace-item"><span>{{ t.action }}</span><span>{{ stateName(t.state) }} <small v-if="t.detail.elapsed_ms">{{ (t.detail.elapsed_ms/1000).toFixed(1) }}s</small></span></div><small>{{ run.id }}</small></details>
  </section>
</template>
